import React, { useRef, useState, useCallback, useEffect, useMemo } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { getEdgeType } from '../data/mindmap';
import NodeEditModal from './NodeEditModal';
import EdgeEditModal from './EdgeEditModal';
import MindMapTopicPage from './MindMapTopicPage';

// ── Dimensions ───────────────────────────────────────────────────
const TW = 180; // topic node width
const TH = 72;  // topic node height

// ── Single topic tile on canvas ──────────────────────────────────
function TopicTile({ node, selected, books, allNodes, allEdges, nodeTypes, onSelect, onDragEnd, onDoubleClick, transform }) {
  const nt = nodeTypes.find(t => t.id === 'topic') || { color: '#2c3e50', label: 'Topic' };
  const isDark = document.documentElement.getAttribute('data-theme') === 'dark';
  const linkedBooks = books.filter(b => (node.bookIds || []).includes(b.id));

  // Count directly connected non-topic nodes
  const connectedIds = new Set();
  allEdges.forEach(e => {
    if (e.source === node.id) connectedIds.add(e.target);
    if (e.target === node.id) connectedIds.add(e.source);
  });
  const connectedNodes = allNodes.filter(n => connectedIds.has(n.id) && n.type !== 'topic');

  // Group counts by type
  const typeCounts = {};
  connectedNodes.forEach(n => { typeCounts[n.type] = (typeCounts[n.type] || 0) + 1; });
  const typeEntries = Object.entries(typeCounts);

  const handleMouseDown = useCallback((e) => {
    if (e.button !== 0) return;
    e.stopPropagation();
    onSelect(node.id);
    const startX = e.clientX, startY = e.clientY;
    const origX = node.x, origY = node.y;
    let curX = origX, curY = origY;
    const onMove = (me) => {
      curX = origX + (me.clientX - startX) / transform.scale;
      curY = origY + (me.clientY - startY) / transform.scale;
      onDragEnd(node.id, curX, curY);
    };
    const onUp = () => { window.removeEventListener('mousemove', onMove); window.removeEventListener('mouseup', onUp); };
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
  }, [node, onSelect, onDragEnd, transform.scale]);

  const bg = isDark ? nt.color + '33' : '#fff';
  const border = selected ? nt.color : isDark ? nt.color + '66' : nt.color + '55';

  return (
    <g transform={`translate(${node.x},${node.y})`}
      onMouseDown={handleMouseDown}
      onDoubleClick={e => { e.stopPropagation(); onDoubleClick(node); }}
      style={{ cursor: 'pointer', userSelect: 'none' }}>

      {/* Glow when selected */}
      {selected && <ellipse cx={TW/2} cy={TH/2} rx={TW/2+6} ry={TH/2+6} fill={nt.color} opacity={0.12} />}

      {/* Card body — pill shape */}
      <rect width={TW} height={TH} rx={TH/2}
        fill={bg}
        stroke={border}
        strokeWidth={selected ? 2.5 : 1.5} />

      {/* Left colour pill accent */}
      <rect x={0} y={0} width={6} height={TH} rx={3} fill={nt.color} opacity={0.8} />

      {/* Topic name */}
      <text x={TW / 2 + 4} y={30} fontSize={13} fontWeight={600}
        fill={isDark ? '#e8e4dc' : nt.color}
        textAnchor="middle" fontFamily="Lora,Georgia,serif"
        fontStyle="italic"
        style={{ pointerEvents: 'none' }}>
        {node.label.length > 18 ? node.label.slice(0, 18) + '…' : node.label}
      </text>

      {/* Connected node count summary */}
      {connectedNodes.length > 0 ? (
        <text x={TW / 2} y={52} fontSize={9}
          fill={isDark ? '#7a7670' : '#8a8680'}
          textAnchor="middle" fontFamily="DM Mono,monospace"
          style={{ pointerEvents: 'none' }}>
          {connectedNodes.length} node{connectedNodes.length !== 1 ? 's' : ''}
          {typeEntries.slice(0, 1).map(([type, count]) => {
            const nt2 = nodeTypes.find(t => t.id === type);
            return nt2 ? ` · ${count} ${nt2.label.toLowerCase()}` : '';
          }).join('')}
        </text>
      ) : (
        <text x={TW / 2 + 4} y={48} fontSize={9}
          fill={isDark ? '#5a5650' : '#b0aca4'}
          textAnchor="middle" fontFamily="DM Mono,monospace"
          style={{ pointerEvents: 'none', fontStyle: 'italic' }}>
          empty · double-click to open
        </text>
      )}

      {/* Book dots bottom-right */}
      {linkedBooks.slice(0, 4).map((b, i) => (
        <circle key={b.id} cx={TW - 8 - i * 9} cy={TH - 7} r={3.5} fill={b.color} />
      ))}

      {/* Hover hint when selected */}
      {selected && (
        <text x={TW / 2} y={TH + 14} fontSize={8} fill={nt.color}
          textAnchor="middle" fontFamily="DM Mono,monospace"
          style={{ pointerEvents: 'none', opacity: 0.75 }}>
          double-click to open →
        </text>
      )}
    </g>
  );
}

// ── Topic-to-topic edge ──────────────────────────────────────────
function TopicEdge({ edge, srcNode, tgtNode, selected, edgeTypes, onSelect, onEdit }) {
  if (!srcNode || !tgtNode) return null;
  const et = edgeTypes.find(t => t.id === edge.type) || getEdgeType(edge.type);
  // Topic nodes are rectangles (centre = x + TW/2, y + TH/2)
  // Non-topic nodes are circles with r=22 (centre = x + 22, y + 22)
  const srcIsCircle = srcNode.type !== 'topic';
  const tgtIsCircle = tgtNode.type !== 'topic';
  const r = 22;
  const sx = srcNode.x + (srcIsCircle ? r : TW / 2);
  const sy = srcNode.y + (srcIsCircle ? r : TH / 2);
  const tx = tgtNode.x + (tgtIsCircle ? r : TW / 2);
  const ty = tgtNode.y + (tgtIsCircle ? r : TH / 2);
  const dx = tx - sx, dy = ty - sy;
  const dist = Math.sqrt(dx * dx + dy * dy) || 1;
  const ux = dx / dist, uy = dy / dist;
  const srcOffset = srcIsCircle ? r + 4 : Math.min(TW / 2 + 8, TH / 2 + 8);
  const tgtOffset = tgtIsCircle ? r + 4 : Math.min(TW / 2 + 8, TH / 2 + 8);
  const x1 = sx + ux * srcOffset, y1 = sy + uy * srcOffset;
  const x2 = tx - ux * tgtOffset, y2 = ty - uy * tgtOffset;
  const col = selected ? '#b07d28' : et.color;
  const arrowId = `arr-${edge.id}`;

  // Bezier control points — curve away from centre for organic feel
  const mx = (x1 + x2) / 2;
  const my = (y1 + y2) / 2;
  const perp = { x: -(y2 - y1) * 0.25, y: (x2 - x1) * 0.25 };
  const cx1 = mx + perp.x;
  const cy1 = my + perp.y;
  const pathD = `M${x1},${y1} Q${cx1},${cy1} ${x2},${y2}`;

  return (
    <g onClick={e => { e.stopPropagation(); onSelect(edge.id); }}
       onDoubleClick={e => { e.stopPropagation(); onEdit(edge); }}
       style={{ cursor: 'pointer' }}>
      <defs>
        <marker id={arrowId} markerWidth={7} markerHeight={5} refX={7} refY={2.5} orient="auto">
          <path d="M0,0 L7,2.5 L0,5 Z" fill={col} opacity={0.9} />
        </marker>
      </defs>
      {/* Fat transparent hit area */}
      <path d={pathD} stroke="transparent" strokeWidth={16} fill="none" />
      {/* Visible curved edge */}
      <path d={pathD}
        stroke={col} strokeWidth={selected ? 2.5 : 1.8}
        strokeDasharray={et.dash ? '6 4' : undefined}
        fill="none"
        markerEnd={`url(#${arrowId})`}
        opacity={selected ? 0.95 : 0.65} />
      {edge.label && (
        <text x={cx1} y={cy1 - 6}
          textAnchor="middle" fontSize={9} fill={et.color}
          fontFamily="DM Mono,monospace" style={{ pointerEvents: 'none' }}
          opacity={0.8}>
          {edge.label}
        </text>
      )}
    </g>
  );
}

// ── Main MindMapView ─────────────────────────────────────────────
export default function MindMapView({ nodes, edges, books, nodeTypes, edgeTypes, onUpdateNodes, onUpdateEdges, onManageNodeTypes, onManageEdgeTypes }) {
  const svgRef = useRef(null);
  const [transform, setTransform] = useState({ x: 80, y: 60, scale: 1 });
  const [selectedNodeId, setSelectedNodeId] = useState(null);
  const [selectedEdgeId, setSelectedEdgeId] = useState(null);
  const [editingNode, setEditingNode] = useState(null);
  const [editingEdge, setEditingEdge] = useState(null);
  const [isNewNode, setIsNewNode] = useState(false);
  const [isNewEdge, setIsNewEdge] = useState(false);
  const [isPanning, setIsPanning] = useState(false);
  const [activeTopicId, setActiveTopicId] = useState(null);
  const [activeTab, setActiveTab] = useState('map');
  const panStart = useRef(null);

  // Only topic nodes shown on canvas
  const topicNodes = useMemo(() => nodes.filter(n => n.type === 'topic'), [nodes]);
  // All edges where both endpoints are topic nodes
  const topicNodeIds = useMemo(() => new Set(topicNodes.map(n => n.id)), [topicNodes]);
  // Show ALL edges — not just topic-to-topic. Any edge between any two nodes.
  const allNodeIds = useMemo(() => new Set(nodes.map(n => n.id)), [nodes]);
  const topicEdges = useMemo(() => edges.filter(e => allNodeIds.has(e.source) && allNodeIds.has(e.target)), [edges, allNodeIds]);

  const selectedNode = nodes.find(n => n.id === selectedNodeId);
  const activeTopic = activeTopicId ? nodes.find(n => n.id === activeTopicId) : null;

  // ── Pan ──────────────────────────────────────────────────────
  const handleSvgMouseDown = useCallback((e) => {
    if (e.button !== 0) return;
    setSelectedNodeId(null); setSelectedEdgeId(null);
    setIsPanning(true);
    panStart.current = { x: e.clientX - transform.x, y: e.clientY - transform.y };
  }, [transform]);

  useEffect(() => {
    const onMove = e => { if (!isPanning || !panStart.current) return; setTransform(t => ({ ...t, x: e.clientX - panStart.current.x, y: e.clientY - panStart.current.y })); };
    const onUp = () => setIsPanning(false);
    window.addEventListener('mousemove', onMove); window.addEventListener('mouseup', onUp);
    return () => { window.removeEventListener('mousemove', onMove); window.removeEventListener('mouseup', onUp); };
  }, [isPanning]);

  // ── Zoom ─────────────────────────────────────────────────────
  const handleWheel = useCallback((e) => {
    e.preventDefault();
    const factor = e.deltaY < 0 ? 1.1 : 0.91;
    const rect = svgRef.current.getBoundingClientRect();
    const px = e.clientX - rect.left, py = e.clientY - rect.top;
    setTransform(t => { const ns = Math.max(0.3, Math.min(3, t.scale * factor)); return { scale: ns, x: px - (px - t.x) * (ns / t.scale), y: py - (py - t.y) * (ns / t.scale) }; });
  }, []);

  useEffect(() => {
    const el = svgRef.current; if (!el) return;
    el.addEventListener('wheel', handleWheel, { passive: false });
    return () => el.removeEventListener('wheel', handleWheel);
  }, [handleWheel]);

  const handleDragEnd = useCallback((id, x, y) => { onUpdateNodes(prev => prev.map(n => n.id === id ? { ...n, x, y } : n)); }, [onUpdateNodes]);

  const handleNodeDoubleClick = (node) => {
    if (node.type === 'topic') { setActiveTopicId(node.id); }
  };

  // ── Add topic ────────────────────────────────────────────────
  const handleAddTopic = () => {
    const rect = svgRef.current?.getBoundingClientRect() || { width: 800, height: 600 };
    // Place new topic with some spacing from existing ones
    const cols = Math.ceil(Math.sqrt(topicNodes.length + 1));
    const idx = topicNodes.length;
    const col = idx % cols, row = Math.floor(idx / cols);
    const x = 60 + col * (TW + 40);
    const y = 60 + row * (TH + 50);
    setEditingNode({ id: uuidv4(), type: 'topic', label: '', note: '', bookIds: [], year: '', x, y });
    setIsNewNode(true);
  };

  const handleSaveNode = updated => { if (isNewNode) onUpdateNodes(prev => [...prev, updated]); else onUpdateNodes(prev => prev.map(n => n.id === updated.id ? updated : n)); };
  const handleDeleteNode = id => { onUpdateNodes(prev => prev.filter(n => n.id !== id)); onUpdateEdges(prev => prev.filter(e => e.source !== id && e.target !== id)); setSelectedNodeId(null); };
  const handleSaveEdge = updated => { if (isNewEdge) onUpdateEdges(prev => [...prev, updated]); else onUpdateEdges(prev => prev.map(e => e.id === updated.id ? updated : e)); };
  const handleDeleteEdge = id => { onUpdateEdges(prev => prev.filter(e => e.id !== id)); setSelectedEdgeId(null); };

  const fitView = () => {
    if (!topicNodes.length || !svgRef.current) return;
    const rect = svgRef.current.getBoundingClientRect();
    const xs = topicNodes.map(n => n.x), ys = topicNodes.map(n => n.y);
    const minX = Math.min(...xs) - 40, maxX = Math.max(...xs) + TW + 40;
    const minY = Math.min(...ys) - 40, maxY = Math.max(...ys) + TH + 40;
    const scale = Math.min(rect.width / (maxX - minX), rect.height / (maxY - minY), 1.8);
    setTransform({ scale, x: -minX * scale + (rect.width - (maxX - minX) * scale) / 2, y: -minY * scale + (rect.height - (maxY - minY) * scale) / 2 });
  };

  // ── Topic page ───────────────────────────────────────────────
  if (activeTopic) {
    return (
      <MindMapTopicPage
        topic={activeTopic}
        allNodes={nodes}
        allEdges={edges}
        books={books}
        nodeTypes={nodeTypes}
        edgeTypes={edgeTypes}
        onBack={() => setActiveTopicId(null)}
        onEditNode={n => { setActiveTopicId(null); setEditingNode(n); setIsNewNode(false); }}
        onSelectNode={id => { setActiveTopicId(null); setSelectedNodeId(id); }}
        onManageNodeTypes={onManageNodeTypes}
        onManageEdgeTypes={onManageEdgeTypes}
        onUpdateNodes={onUpdateNodes}
        onUpdateEdges={onUpdateEdges}
      />
    );
  }

  const nonTopicCount = nodes.filter(n => n.type !== 'topic').length;

  // ── Interconnection matrix data ──────────────────────────────────
  const connectionMatrix = topicNodes.map(node => {
    const outgoing = topicEdges.filter(e => e.source === node.id);
    const incoming = topicEdges.filter(e => e.target === node.id);
    return {
      node,
      connections: [
        ...outgoing.map(e => {
          const target = topicNodes.find(n => n.id === e.target);
          const et = edgeTypes.find(t => t.id === e.type);
          return { direction: 'out', other: target, edge: e, typeLabel: et?.label || e.type, color: et?.color || 'var(--accent)' };
        }),
        ...incoming.map(e => {
          const source = topicNodes.find(n => n.id === e.source);
          const et = edgeTypes.find(t => t.id === e.type);
          return { direction: 'in', other: source, edge: e, typeLabel: et?.label || e.type, color: et?.color || 'var(--accent)' };
        }),
      ].filter(c => c.other),
    };
  }).filter(n => n.connections.length > 0)
    .sort((a, b) => b.connections.length - a.connections.length);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      {/* ── META HEADER ──────────────────────────────────── */}
      <div style={{ padding: '11px 20px 9px', borderBottom: '2px solid var(--paper-3)', flexShrink: 0, background: 'var(--paper-2)', position: 'relative', overflow: 'hidden' }}>
        {/* Watermark */}
        <div style={{ position: 'absolute', right: 20, top: '50%', transform: 'translateY(-50%)', fontSize: 9, color: 'var(--accent)', opacity: 0.13, fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.2em', pointerEvents: 'none', userSelect: 'none', whiteSpace: 'nowrap', textTransform: 'uppercase' }}>
          METAVERSE · LAGOS PROTOCOL · NEURAL CONSTRUCT LAYER
        </div>

        <div style={{ display: 'flex', alignItems: 'flex-start', gap: 16 }}>
          <div>
            <div style={{ fontSize: 8, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.14em', textTransform: 'uppercase', marginBottom: 2 }}>
              Neural construct · connection layer
            </div>
            <div style={{ fontSize: 18, fontFamily: 'var(--font-display)', fontWeight: 700, color: 'var(--ink)', lineHeight: 1.2 }}>META</div>
            <div style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', marginTop: 2, letterSpacing: '0.04em' }}>
              {topicNodes.length} node{topicNodes.length !== 1 ? 's' : ''} · {topicEdges.length} connection{topicEdges.length !== 1 ? 's' : ''}
            </div>
          </div>

          <div style={{ marginLeft: 'auto', display: 'flex', gap: 6, alignItems: 'center' }}>
            {/* Tab toggle */}
            <div style={{ display: 'flex', border: '1px solid var(--paper-3)', borderRadius: 2, overflow: 'hidden' }}>
              {[['map','⊛ Map'],['connections','↔ Connections']].map(([t, label]) => (
                <button key={t} onClick={() => setActiveTab(t)}
                  style={{ padding: '5px 12px', fontSize: 10, border: 'none', borderRight: t==='map'?'1px solid var(--paper-3)':'none', background: activeTab===t?'var(--ink)':'transparent', color: activeTab===t?'var(--paper-card)':'var(--ink-3)', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.06em' }}>
                  {label}
                </button>
              ))}
            </div>

            {activeTab === 'map' && <>
              <ToolBtn onClick={fitView}>⊡ Fit</ToolBtn>
              <ToolBtn onClick={() => setTransform(t => ({ ...t, scale: Math.min(t.scale * 1.2, 3) }))}>＋</ToolBtn>
              <ToolBtn onClick={() => setTransform(t => ({ ...t, scale: Math.max(t.scale * 0.83, 0.3) }))}>－</ToolBtn>
              {topicNodes.length > 1 && (
                <>
                  <div style={{ width: 1, height: 18, background: 'var(--paper-3)' }} />
                  <ToolBtn onClick={() => { setEditingEdge({ id: uuidv4(), source: selectedNodeId || '', target: '', type: edgeTypes[0]?.id || 'related', label: '' }); setIsNewEdge(true); }}>
                    + Link
                  </ToolBtn>
                  {selectedEdgeId && (() => {
                    const selEdge = edges.find(e => e.id === selectedEdgeId);
                    return selEdge ? (
                      <ToolBtn onClick={() => { setEditingEdge({ ...selEdge }); setIsNewEdge(false); }}>
                        ✎ Edit link
                      </ToolBtn>
                    ) : null;
                  })()}
                </>
              )}
              <button onClick={handleAddTopic} style={{ fontSize: 10, padding: '5px 16px', borderRadius: 2, background: 'var(--ink)', color: 'var(--paper-card)', border: 'none', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.07em' }}>
                + NODE
              </button>
            </>}
          </div>
        </div>
      </div>

      {/* ── MAP TAB ───────────────────────────────────────── */}
      {activeTab === 'map' && (
      <div style={{ flex: 1, position: 'relative', overflow: 'hidden', background: 'var(--paper)' }}>
        <svg ref={svgRef} width="100%" height="100%"
          onMouseDown={handleSvgMouseDown}
          style={{ cursor: isPanning ? 'grabbing' : 'default', display: 'block' }}>

          {/* Dot grid */}
          <defs>
            <radialGradient id="mm-bg" cx="50%" cy="50%" r="70%">
              <stop offset="0%" stopColor="var(--paper)" stopOpacity="1" />
              <stop offset="100%" stopColor="var(--paper-2)" stopOpacity="1" />
            </radialGradient>
            <pattern id="mm-grid" width={32 * transform.scale} height={32 * transform.scale}
              patternTransform={`translate(${transform.x % (32 * transform.scale)},${transform.y % (32 * transform.scale)})`}
              patternUnits="userSpaceOnUse">
              <circle cx={0} cy={0} r={0.7} fill="var(--paper-3)" opacity="0.5" />
            </pattern>
          </defs>
          <rect width="100%" height="100%" fill="url(#mm-bg)" />
          <rect width="100%" height="100%" fill="url(#mm-grid)" />

          <g transform={`translate(${transform.x},${transform.y}) scale(${transform.scale})`}>
            {/* Topic-to-topic edges */}
            {topicEdges.map(edge => (
              <TopicEdge key={edge.id} edge={edge}
                srcNode={nodes.find(n => n.id === edge.source)}
                tgtNode={nodes.find(n => n.id === edge.target)}
                selected={selectedEdgeId === edge.id}
                edgeTypes={edgeTypes}
                onSelect={setSelectedEdgeId}
                onEdit={e => { setEditingEdge({...e}); setIsNewEdge(false); }} />
            ))}

            {nodes.filter(n => n.type !== 'topic').map(node => {
              const nt = nodeTypes.find(t => t.id === node.type) || { color: '#7a6a52', label: node.type };
              const isSelected = selectedNodeId === node.id;
              const r = 22;
              const handleDrag = (e) => {
                e.stopPropagation();
                setSelectedNodeId(node.id);
                const startX = e.clientX, startY = e.clientY;
                const origX = node.x, origY = node.y;
                const onMove = (me) => {
                  const nx = origX + (me.clientX - startX) / transform.scale;
                  const ny = origY + (me.clientY - startY) / transform.scale;
                  onUpdateNodes(prev => prev.map(n => n.id === node.id ? {...n, x: nx, y: ny} : n));
                };
                const onUp = () => { window.removeEventListener('mousemove', onMove); window.removeEventListener('mouseup', onUp); };
                window.addEventListener('mousemove', onMove);
                window.addEventListener('mouseup', onUp);
              };
              return (
                <g key={node.id}
                  transform={`translate(${node.x + r},${node.y + r})`}
                  onMouseDown={handleDrag}
                  style={{ cursor: 'grab', userSelect: 'none' }}>
                  {isSelected && <circle cx={0} cy={0} r={r+6} fill={nt.color} opacity={0.15} />}
                  <circle cx={0} cy={0} r={r} fill={nt.color + '22'} stroke={nt.color} strokeWidth={isSelected?2.5:1.5} />
                  <text x={0} y={-r-5} fontSize={10} fill={nt.color}
                    textAnchor="middle" fontFamily="Lora,Georgia,serif" fontStyle="italic"
                    style={{ pointerEvents:'none' }}>
                    {node.label.length > 14 ? node.label.slice(0,14)+'…' : node.label}
                  </text>
                  {node.year && (
                    <text x={0} y={5} fontSize={8} fill={nt.color} opacity={0.7}
                      textAnchor="middle" fontFamily="DM Mono,monospace"
                      style={{ pointerEvents:'none' }}>
                      {node.year}
                    </text>
                  )}
                  <text x={0} y={-7} fontSize={7} fill={nt.color} opacity={0.6}
                    textAnchor="middle" fontFamily="DM Mono,monospace"
                    style={{ pointerEvents:'none', textTransform:'uppercase', letterSpacing:'0.05em' }}>
                    {nt.label}
                  </text>
                </g>
              );
            })}

            {/* Topic tiles */}
            {topicNodes.map(node => (
              <TopicTile key={node.id} node={node}
                selected={selectedNodeId === node.id}
                books={books}
                allNodes={nodes}
                allEdges={edges}
                nodeTypes={nodeTypes}
                onSelect={setSelectedNodeId}
                onDragEnd={handleDragEnd}
                onDoubleClick={handleNodeDoubleClick}
                transform={transform} />
            ))}
          </g>
        </svg>

        {/* Empty state */}
        {topicNodes.length === 0 && (
          <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 12, pointerEvents: 'none' }}>
            <div style={{ fontSize: 36, opacity: 0.15 }}>✦</div>
            <div style={{ fontSize: 15, color: 'var(--ink-4)', fontStyle: 'italic' }}>No topics yet</div>
            <div style={{ fontSize: 12, color: 'var(--ink-4)', maxWidth: 260, textAlign: 'center', lineHeight: 1.6 }}>
              Click "+ New topic" to add your first topic — Time, Body, God, Language, whatever you're exploring.
            </div>
          </div>
        )}

        {/* Zoom % */}
        <div style={{ position: 'absolute', bottom: 14, right: 14, fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', background: 'var(--paper-card)', border: '1px solid var(--paper-3)', borderRadius: 5, padding: '3px 8px' }}>
          {Math.round(transform.scale * 100)}%
        </div>

        {/* Mini legend */}
        <div style={{ position: 'absolute', bottom: 14, left: 14, background: 'var(--paper-card)', border: '1px solid var(--paper-3)', borderRadius: 8, padding: '8px 12px', fontSize: 11 }}>
          <div style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', marginBottom: 4, textTransform: 'uppercase', letterSpacing: '0.06em' }}>Canvas</div>
          <div style={{ color: 'var(--ink-3)', lineHeight: 1.7 }}>Click → select<br />Double-click → open topic<br />Drag → reposition<br />Scroll → zoom</div>
        </div>
      </div>
      )} {/* end map tab */}

      {/* ── CONNECTIONS TAB ───────────────────────────────── */}
      {activeTab === 'connections' && (
        <div style={{ flex: 1, overflowY: 'auto', padding: '20px 24px' }}>
          {topicEdges.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '60px 0', color: 'var(--ink-4)' }}>
              <div style={{ fontSize: 36, opacity: 0.08, marginBottom: 12, fontFamily: 'var(--font-display)' }}>◌</div>
              <div style={{ fontSize: 13, fontStyle: 'italic', lineHeight: 1.8 }}>
                No connections yet. Link nodes in the Map tab to build the web.
              </div>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>

              {/* Summary stats */}
              <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', marginBottom: 4 }}>
                {[
                  { label: 'nodes', value: topicNodes.length },
                  { label: 'connections', value: topicEdges.length },
                  { label: 'isolated nodes', value: topicNodes.filter(n => !topicEdges.some(e => e.source===n.id||e.target===n.id)).length },
                  { label: 'most connected', value: connectionMatrix[0]?.node.label || '—' },
                ].map(s => (
                  <div key={s.label} style={{ background: 'var(--paper-card)', border: '1px solid var(--paper-3)', borderRadius: 2, padding: '8px 14px' }}>
                    <div style={{ fontSize: 16, fontFamily: 'var(--font-display)', fontWeight: 700, color: 'var(--ink)', lineHeight: 1 }}>{s.value}</div>
                    <div style={{ fontSize: 9, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', marginTop: 3, letterSpacing: '0.06em', textTransform: 'uppercase' }}>{s.label}</div>
                  </div>
                ))}
              </div>

              {/* Node connection list */}
              {connectionMatrix.map(({ node, connections }) => {
                const nodeType = nodeTypes.find(t => t.id === node.type);
                return (
                  <div key={node.id} style={{ background: 'var(--paper-card)', border: '1px solid var(--paper-3)', borderRadius: 2, overflow: 'hidden' }}>
                    {/* Node header */}
                    <div style={{ padding: '10px 16px', background: 'var(--paper-2)', borderBottom: '1px solid var(--paper-3)', display: 'flex', alignItems: 'center', gap: 10 }}>
                      <div style={{ width: 8, height: 8, borderRadius: '50%', background: nodeType?.color || 'var(--accent)', flexShrink: 0 }} />
                      <span style={{ fontSize: 13, fontFamily: 'var(--font-display)', fontStyle: 'italic', fontWeight: 600, color: 'var(--ink)', flex: 1 }}>{node.label}</span>
                      <span style={{ fontSize: 9, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.05em' }}>
                        {connections.length} connection{connections.length !== 1 ? 's' : ''}
                      </span>
                    </div>

                    {/* Connections */}
                    {connections.map((c, i) => (
                      <div key={c.edge.id + i} style={{ padding: '8px 16px', borderBottom: i < connections.length-1 ? '1px dashed var(--paper-3)' : 'none', display: 'flex', alignItems: 'center', gap: 10 }}>
                        {/* Direction arrow */}
                        <span style={{ fontSize: 10, color: c.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal', flexShrink: 0, width: 16, textAlign: 'center' }}>
                          {c.direction === 'out' ? '→' : '←'}
                        </span>
                        {/* Connection type badge */}
                        <span style={{ fontSize: 8, padding: '2px 7px', borderRadius: 2, background: c.color + '18', color: c.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.06em', flexShrink: 0 }}>
                          {c.typeLabel.toUpperCase()}
                        </span>
                        {/* Other node */}
                        <span style={{ fontSize: 12, color: 'var(--ink-2)', fontFamily: 'var(--font-serif)', fontStyle: 'italic', flex: 1 }}>
                          {c.other?.label || 'Unknown node'}
                        </span>
                        {/* Edge label if exists */}
                        {c.edge.label && (
                          <span style={{ fontSize: 10, color: 'var(--ink-4)', fontStyle: 'italic' }}>"{c.edge.label}"</span>
                        )}
                        {/* Edit button */}
                        <button
                          onClick={() => { setEditingEdge({...c.edge}); setIsNewEdge(false); setActiveTab('map'); }}
                          style={{ fontSize: 9, color: 'var(--ink-4)', background: 'none', border: '1px solid var(--paper-3)', borderRadius: 2, cursor: 'pointer', padding: '2px 7px', fontFamily: 'var(--font-mono)', fontStyle: 'normal', flexShrink: 0 }}
                          onMouseEnter={e => { e.currentTarget.style.color = 'var(--accent)'; e.currentTarget.style.borderColor = 'var(--accent-2)'; }}
                          onMouseLeave={e => { e.currentTarget.style.color = 'var(--ink-4)'; e.currentTarget.style.borderColor = 'var(--paper-3)'; }}>
                          ✎
                        </button>
                      </div>
                    ))}
                  </div>
                );
              })}

              {/* Isolated nodes */}
              {(() => {
                const isolated = topicNodes.filter(n => !topicEdges.some(e => e.source===n.id||e.target===n.id));
                if (!isolated.length) return null;
                return (
                  <div>
                    <div style={{ fontSize: 9, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.1em', textTransform: 'uppercase', marginBottom: 8, paddingBottom: 6, borderBottom: '1px dashed var(--paper-3)' }}>
                      Isolated — no connections
                    </div>
                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
                      {isolated.map(n => (
                        <span key={n.id} style={{ fontSize: 11, padding: '4px 10px', border: '1px dashed var(--paper-3)', borderRadius: 2, color: 'var(--ink-4)', fontStyle: 'italic', fontFamily: 'var(--font-serif)' }}>
                          {n.label}
                        </span>
                      ))}
                    </div>
                  </div>
                );
              })()}
            </div>
          )}
        </div>
      )}

      {/* Modals */}
      {editingNode && (
        <NodeEditModal node={editingNode} books={books} nodeTypes={nodeTypes} isNew={isNewNode}
          onSave={handleSaveNode} onDelete={handleDeleteNode}
          onClose={() => setEditingNode(null)} onManageTypes={onManageNodeTypes} />
      )}
      {editingEdge && (
        <EdgeEditModal edge={editingEdge} nodes={topicNodes} edgeTypes={edgeTypes} isNew={isNewEdge}
          onSave={handleSaveEdge} onDelete={handleDeleteEdge}
          onClose={() => setEditingEdge(null)} onManageTypes={onManageEdgeTypes} />
      )}
    </div>
  );
}

function ToolBtn({ onClick, children }) {
  return (
    <button onClick={onClick} style={{ fontSize: 12, padding: '5px 12px', borderRadius: 6, border: '1px solid var(--paper-3)', color: 'var(--ink-2)', background: 'var(--paper-card)', cursor: 'pointer' }}
      onMouseEnter={e => { e.currentTarget.style.borderColor = 'var(--accent-2)'; e.currentTarget.style.color = 'var(--accent)'; }}
      onMouseLeave={e => { e.currentTarget.style.borderColor = 'var(--paper-3)'; e.currentTarget.style.color = 'var(--ink-2)'; }}>
      {children}
    </button>
  );
}
